import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/commands.md","filePath":"en/modules/item/commands.md","lastUpdated":0}`),a={name:`en/modules/item/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiItem is <code>/emakiitem</code>, with <code>/ei</code> as an alias. Commands list item definitions, give items, inspect held items, inspect Minecraft item components, refresh player items and set state, reload configuration, and print debug output.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ei help</code></td><td>None</td><td>Print command help. Running <code>/ei</code> without arguments is equivalent to <code>help</code>.</td></tr><tr><td><code>/ei list [page]</code></td><td><code>emakiitem.use</code></td><td>List loaded item definitions, 10 per page.</td></tr><tr><td><code>/ei browse [page]</code></td><td><code>emakiitem.browse</code></td><td>Open the item browser listing item packs; player-only. See <a href="./browser.html">Browser GUI</a>.</td></tr><tr><td><code>/ei give &lt;player&gt; &lt;id&gt; [amount]</code></td><td><code>emakiitem.give</code></td><td>Give an EmakiItem item to a player.</td></tr><tr><td><code>/ei inspect [player]</code></td><td><code>emakiitem.inspect</code></td><td>Inspect the target player&#39;s main-hand item, including item id, versions, attributes, skills, and set PDC state.</td></tr><tr><td><code>/ei components [yaml] [player] [component_id]</code></td><td><code>emakiitem.inspect</code></td><td>Inspect Minecraft item components. JSON remains the default; YAML is produced only when <code>yaml</code> is explicit. <code>/ei component</code> is also accepted.</td></tr><tr><td><code>/ei repair</code></td><td><code>emakiitem.use</code></td><td>Open the equipment repair interface for yourself. Players only.</td></tr><tr><td><code>/ei state query|repair|recompute [player]</code></td><td><code>emakiitem.inspect</code> (<code>query</code>) / <code>emakiitem.admin</code> (<code>repair</code>, <code>recompute</code>)</td><td>Query, repair, or recompute the main-hand item&#39;s item state. Omitting the sub-command is treated as <code>query</code>.</td></tr><tr><td><code>/ei update [player]</code></td><td><code>emakiitem.update</code></td><td>Refresh EmakiItem items in the player&#39;s inventory and recalculate set state.</td></tr><tr><td><code>/ei alias list|add|remove</code></td><td><code>emakiitem.admin</code></td><td>List, add, or remove item ID aliases.</td></tr><tr><td><code>/ei migrate id|inventory</code></td><td><code>emakiitem.admin</code></td><td>Preview or apply an item ID migration, or migrate player inventories.</td></tr><tr><td><code>/ei reload</code></td><td><code>emakiitem.reload</code></td><td>Reload items, sets, config, and language.</td></tr><tr><td><code>/ei debug [stats|player|module|on|off]</code></td><td><code>emakiitem.debug</code> or <code>emakiitem.admin</code></td><td>Print runtime debug information; <code>stats</code> prints refresh metrics.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiitem.use</code></td><td>true</td><td>Allows basic command usage and item listing.</td></tr><tr><td><code>emakiitem.give</code></td><td>op</td><td>Allows giving custom items.</td></tr><tr><td><code>emakiitem.browse</code></td><td>op</td><td>Allows opening the item browser and taking items from it.</td></tr><tr><td><code>emakiitem.inspect</code></td><td>op</td><td>Allows inspecting item state and Minecraft components.</td></tr><tr><td><code>emakiitem.update</code></td><td>op</td><td>Allows refreshing player item and set state.</td></tr><tr><td><code>emakiitem.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiitem.debug</code></td><td>op</td><td>Allows debug output.</td></tr><tr><td><code>emakiitem.admin</code></td><td>op</td><td>Allows alias and migration commands, and acts as the administrative fallback for debug access.</td></tr></tbody></table><p>The root <code>/emakiitem</code> command itself requires <code>emakiitem.use</code>, which the <code>repair</code> subcommand also uses.</p><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to “Common operations”">​</a></h2><h3 id="list-items" tabindex="-1">List items <a class="header-anchor" href="#list-items" aria-label="Permalink to “List items”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei list</span></span>
<span class="line"><span>/ei list 2</span></span></code></pre></div><p>Use this to confirm that files under <code>plugins/EmakiItem/items/</code> loaded successfully. The list shows config ids and display names.</p><h3 id="browse-and-take-items" tabindex="-1">Browse and take items <a class="header-anchor" href="#browse-and-take-items" aria-label="Permalink to “Browse and take items”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei browse</span></span>
<span class="line"><span>/ei browse 2</span></span></code></pre></div><p>The first level lists item packs; clicking a pack icon opens the second level, where a left click takes one piece and Shift + left click takes a full stack. Unlike <code>/ei give</code>, which needs the item id up front, the browser is meant for looking around.</p><h3 id="give-an-item" tabindex="-1">Give an item <a class="header-anchor" href="#give-an-item" aria-label="Permalink to “Give an item”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei give Steve example_item 1</span></span></code></pre></div><p>After giving the item, the plugin runs the item&#39;s <code>actions.give</code>, refreshes the player&#39;s EmakiItem items and set state, and schedules Attribute equipment sync. If giving fails, confirm that the item id exists.</p><h3 id="inspect-the-held-item" tabindex="-1">Inspect the held item <a class="header-anchor" href="#inspect-the-held-item" aria-label="Permalink to “Inspect the held item”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei inspect</span></span>
<span class="line"><span>/ei inspect Steve</span></span></code></pre></div><p><code>inspect</code> reads the target player&#39;s main-hand item and prints:</p><ul><li>EmakiItem id;</li><li>schema / update versions;</li><li>whether the item definition still exists;</li><li>Attribute PDC written under the <code>emakiitem</code> namespace (<code>attributes</code> and <code>attribute_meta</code>);</li><li>skill ids and forced equipment skill triggers;</li><li>definition signature;</li><li>set id, set piece, active count, total count, and active thresholds.</li></ul><p>When debugging missing attributes, set bonuses, or skills, inspect real PDC state instead of relying on lore only.</p><h3 id="inspect-minecraft-item-components" tabindex="-1">Inspect Minecraft item components <a class="header-anchor" href="#inspect-minecraft-item-components" aria-label="Permalink to “Inspect Minecraft item components”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei components</span></span>
<span class="line"><span>/ei components Steve</span></span>
<span class="line"><span>/ei components Steve custom_model_data</span></span>
<span class="line"><span>/ei components yaml</span></span>
<span class="line"><span>/ei components yaml Steve custom_model_data</span></span>
<span class="line"><span>/ei component custom_model_data</span></span></code></pre></div><p>Without a format argument, <code>components</code> preserves the existing JSON output. Only <code>components yaml ...</code> emits structured YAML. YAML export is based on the stable vanilla component string and never treats <code>String.valueOf(DataComponentValue)</code> as a persistence format. Command arguments may omit <code>minecraft:</code>, and YAML export uses short IDs for vanilla components while preserving explicit non-Minecraft namespaces. Component id lines can be clicked to copy the id. This is useful for Minecraft 1.21+ components such as:</p><ul><li><code>minecraft:custom_model_data</code></li><li><code>minecraft:item_model</code></li><li><code>minecraft:tooltip_style</code></li><li><code>minecraft:enchantments</code></li><li><code>minecraft:attribute_modifiers</code></li></ul><p>If the player name is omitted and the sender is a player, the command inspects the sender&#39;s main-hand item. If the second argument is not an online player name, it is treated as a component id.</p><h3 id="refresh-items-and-sets" tabindex="-1">Refresh items and sets <a class="header-anchor" href="#refresh-items-and-sets" aria-label="Permalink to “Refresh items and sets”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei update</span></span>
<span class="line"><span>/ei update Steve</span></span></code></pre></div><p>Use this after changing item definitions, set definitions, update rules, or equipment state. The command refreshes EmakiItem items in the player&#39;s inventory and recalculates equipped set state. If anything changes, Attribute equipment sync is scheduled.</p><h3 id="open-the-repair-interface" tabindex="-1">Open the repair interface <a class="header-anchor" href="#open-the-repair-interface" aria-label="Permalink to “Open the repair interface”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei repair</span></span></code></pre></div><p>Players only; opens the repair interface defined by <code>gui/repair_gui.yml</code> for the sender. If the template is missing, the command reports that opening failed.</p><h3 id="manage-id-aliases" tabindex="-1">Manage ID aliases <a class="header-anchor" href="#manage-id-aliases" aria-label="Permalink to “Manage ID aliases”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei alias list</span></span>
<span class="line"><span>/ei alias add old_sword flame_sword</span></span>
<span class="line"><span>/ei alias remove old_sword</span></span></code></pre></div><p><code>add</code> requires the target item ID to be loaded, otherwise it reports that the item does not exist. Alias changes are written back to <code>id_aliases.yml</code> and clear the item factory cache.</p><h3 id="migrate-item-ids-and-inventories" tabindex="-1">Migrate item IDs and inventories <a class="header-anchor" href="#migrate-item-ids-and-inventories" aria-label="Permalink to “Migrate item IDs and inventories”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei migrate id old_sword flame_sword --dry-run</span></span>
<span class="line"><span>/ei migrate id old_sword flame_sword --apply</span></span>
<span class="line"><span>/ei migrate inventory Steve</span></span>
<span class="line"><span>/ei migrate inventory all</span></span></code></pre></div><p><code>migrate id</code> requires an explicit <code>--dry-run</code> or <code>--apply</code>. <code>--dry-run</code> only reports the replacement count and affected files; <code>--apply</code> performs the replacement and keeps an alias. <code>migrate inventory</code> rewrites legacy IDs in the target player&#39;s inventory (or all online players) and also refreshes sets and Attribute equipment sync.</p><h3 id="reload-configuration" tabindex="-1">Reload configuration <a class="header-anchor" href="#reload-configuration" aria-label="Permalink to “Reload configuration”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei reload</span></span></code></pre></div><p>This reloads items, sets, config, and language. On production servers, validate new config on a test server first, then run <code>/ei update</code> for online players when needed.</p><h3 id="inspect-refresh-metrics" tabindex="-1">Inspect refresh metrics <a class="header-anchor" href="#inspect-refresh-metrics" aria-label="Permalink to “Inspect refresh metrics”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ei debug stats</span></span></code></pre></div><p>Prints item/set refresh event counts, batches, coalesced batches, requested versus actual refresh scope, cache hits, scanned slots, changes, conflicts, and elapsed time. Available debug modules are <code>create</code>, <code>update</code>, <code>identify</code>, <code>set</code>, <code>item_operation</code>, and <code>pdc</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Item id is missing from the list: check <code>items/*.yml</code>, <code>id</code>, YAML indentation, and console load errors.</li><li>Attributes do not apply after giving: use <code>/ei inspect</code> to check <code>attributes</code> and <code>attribute_meta</code>, then confirm EmakiAttribute is installed.</li><li>Set bonuses do not trigger: use <code>/ei inspect</code> to check <code>set_id</code>, <code>set_piece</code>, <code>set_active_count</code>, and <code>set_active_thresholds</code>.</li><li>Components look wrong: use <code>/ei components</code> to inspect actual Bukkit components, then fix the <code>item.components</code> section in the item definition.</li><li>Old items did not update: confirm <code>update.enabled</code>, <code>update.version</code>, and update triggers in the item definition, then run <code>/ei update &lt;player&gt;</code>.</li></ul>`,47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};